{текст: 'Стр. ' + (видна + 1) + ': ' + как + ' — ' + стр_(т.строки.length, 'строка', 'строки', 'строк') + ' × ' + стр_(ш, 'столбец', 'столбца', 'столбцов') + '\n', жирный: true}];
