function Щелчок(){ const п = параметры({}); if(п.щелчок) щелчок = п.щелчок; }
async function Мышь(){ return безСбоя(async () => {
const п = повод();
if(п.вид !== 'нажатие' || !вид || !pdf) return;
const пп = параметры({}); if(пп.щелчок) щелчок = пп.щелчок;
const x = (п.x - вид.ox) / вид.s, y = (п.y - вид.oy) / вид.s;
if(x < 0 || y < 0 || x > вид.с.ш || y > вид.с.в) return;
if(/верх|низ/.test(щелчок)){
const ключ = пп.всем ? '*' : видна;
const к = Object.assign({}, обрезка[ключ] || обрезка[видна] || обрезка['*'] || {});
if(/верх/.test(щелчок)) к.верх = y; else к.низ = y;
if(к.верх != null && к.низ != null && к.верх >= к.низ){ if(/верх/.test(щелчок)) к.низ = null; else к.верх = null; }
if(пп.всем){ обрезка = {'*': к}; } else обрезка[видна] = к;
} else {
if(!(границы && границы.length)){
const ряды = вид.т.ряды || [];
const x0 = ряды.length ? Math.min(...ряды.map(р => р.отрезки[0].x1)) : 0, x1 = ряды.length ? Math.max(...ряды.map(р => р.отрезки[р.отрезки.length - 1].x2)) : вид.с.ш;
границы = вид.т.вид === 'нет' ? [] : (вид.т.границы || []).filter(b => b > x0 + 1 && b < x1 - 1);
}
const k = границы.findIndex(b => Math.abs(b - x) * вид.s <= 6);
if(k >= 0) границы.splice(k, 1); else { границы.push(x); границы.sort((a, b) => a - b); }
if(!границы.length) границы = null;
}
await показать();
}); }
async function Клавиша(){ const п = повод(); if(п.вид !== 'нажата') return; if(п.клавиша === 'ArrowLeft' || п.клавиша === 'PageUp') return Назад(); if(п.клавиша === 'ArrowRight' || п.клавиша === 'PageDown') return Вперёд(); }
async function Назад(){ return безСбоя(async () => { if(!pdf) return; видна = (видна - 1 + pdf.узлы.length) % pdf.узлы.length; await показать(); }); }
